  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C10","C13","C24","C25","C27"],
  "contradictory_card_ids": ["C20"],
  "prediction_basis_card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C10","C13"],
  "claims": [
    {
      "claim": "The anthranilic acid fenamate contexts most similar to the query's core show high human oral bioavailability: meclofenamate >85% and flufenamic acid good absorption, supporting F>=20%.",
      "card_ids": ["C05","C02"]
    },
    {
      "claim": "Other acidic aromatic carboxylic acids with absolute or systemic availability records are at or above threshold: diflunisal 89.5% absolute and 2,4-D rapid/complete (virtually 100% in rats).",
      "card_ids": ["C07","C08","C24","C27"]
    },
    {
      "claim": "Sulfonamide-containing comparators with lower F still meet the threshold: celecoxib 20-40% and pazopanib absolute mean 21.4%.",
      "card_ids": ["C06","C10"]
    },
    {
      "claim": "Telmisartan absolute bioavailability is at least 42% in humans, providing another high-F comparator.",
      "card_ids": ["C04","C13"]
    },
    {
      "claim": "L2 meclofenamic acid in horses (64-90% absolute, mean 76%) reinforces the high human meclofenamate record but is nonvoting context.",
      "card_ids": ["C25"]
    },
    {
      "claim": "L3 oral Cmax records are for other molecules and report exposure without matched IV F; they are indirect and do not establish F<20%.",
      "card_ids": ["C30","C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41"]
    },
    {
      "claim": "The only low-F record, PA-96 ~7% in mice, lacks a defined structure and is low-transferability; it does not affirmatively support F<20%.",
      "card_ids": ["C20"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C30","C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41"]
    }
  ],
  "evidence_gaps": [
    "No direct furosemide oral bioavailability record is present; all endpoint evidence comes from structurally related contexts.",
    "No cystic fibrosis-specific pharmacokinetic data are available; transfer from no-condition contexts is inferred.",
    "L3 records report Cmax only, without matched IV AUC or dose-normalized F, so they cannot directly establish the F>=20% threshold.",
    "The query prior indicates very low passive permeability (logD -2.53, TPSA 122.6, neutral fraction 0), but this is a physicochemical prior, not a measured F outcome.",
    "PA-96 low-F record lacks a defined structure and is from mice; transferability to the query is low.",
    "Pazopanib's absolute F range (13.5-38.9%) includes values below 20%, but its mean is above threshold."
  ],
  "decision_summary": "Predicted high (F>=20%) because the most transferable record cards—anthranilic acid fenamates (meclofenamate >85%, flufenamic acid good), acidic aromatic acids (diflunisal 89.5%, 2,4-D rapid/complete), and sulfonamide comparators (celecoxib 20-40%, pazopanib 21.4%)—support F at or above 20%, and no cited record affirmatively establishes F<20% for a structurally similar molecule. L3 Cmax records are indirect and do not change the decision; the low physicochemical prior is not endpoint proof."
}

